window.docContents[181].resolve({"/Preface/#Logical-Foundations--Preface--Resources--Sample-Exams":{"contents":"A large compendium of exams from many offerings of\nCIS5000 (\"Software Foundations\") at the University of Pennsylvania\ncan be found at\n<https://www.seas.upenn.edu/~cis5000/current/exams/index.html>.\nThere has been some drift of notations over the years, but most of\nthe problems are still relevant to the current text.\n\n","context":"Logical Foundations\u0009Preface\u0009Resources","header":"1.4.1. Sample Exams","id":"/Preface/#Logical-Foundations--Preface--Resources--Sample-Exams"}});